const eyeW=new G.MeshStandardMaterial({color:0xf2eee8,roughness:.3}),iris=new G.MeshStandardMaterial({color:0x3b6e8f,roughness:.2}),lipM=new G.MeshStandardMaterial({color:0xa5574d,roughness:.5});
